<!-- Generated by Trae Work -->
<script setup lang="ts">
/**
 * @file BPMN 2.0 专业流程设计器（基于 bpmn.js）
 * @module components/BpmnDesigner
 * @description P0-01: 引入 bpmn.js 替换自绘 SVG，对标炎黄盈动/奥哲 BPMN 建模工具。
 *   支持拖拽式 BPMN 2.0 建模、属性编辑、XML 导入导出、模板加载。
 */
import { ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { ElMessage } from 'element-plus'
import BpmnModeler from 'bpmn-js/lib/Modeler'
import 'bpmn-js/dist/assets/diagram-js.css'
import 'bpmn-js/dist/assets/bpmn-js.css'
import 'bpmn-js/dist/assets/bpmn-font/css/bpmn.css'
import { deployDefinition } from '@/api/workflow'
import type { FlowDeployDTO } from '@/api/workflow/types'

// ==================== Props ====================
const props = defineProps<{
  /** 初始 BPMN XML（编辑已有流程时传入） */
  initialXml?: string
  /** 流程编码 */
  flowCode?: string
  /** 流程名称 */
  flowName?: string
  /** 流程类别 */
  category?: string
}>()

const emit = defineEmits<{
  (e: 'save', xml: string, svg: string): void
  (e: 'deploy', flowCode: string, flowName: string, xml: string): void
}>()

// ==================== State ====================
const containerRef = ref<HTMLDivElement>()
const loading = ref(false)
const saving = ref(false)
const currentXml = ref('')
const currentSvg = ref('')
const modeler = ref<BpmnModeler | null>(null)

const deployForm = ref({
  flowCode: props.flowCode || '',
  flowName: props.flowName || '',
  category: props.category || 'GENERAL',
  formPath: '',
})

// ==================== Lifecycle ====================
onMounted(async () => {
  await nextTick()
  initModeler()
})

onBeforeUnmount(() => {
  if (modeler.value) {
    modeler.value.destroy()
    modeler.value = null
  }
})

watch(() => props.initialXml, (newVal) => {
  if (newVal && modeler.value) {
    loadXml(newVal)
  }
})

// ==================== Init ====================
function initModeler() {
  if (!containerRef.value) return

  loading.value = true
  try {
    const m = new BpmnModeler({
      container: containerRef.value,
      keyboard: { bindTo: document },
      additionalModules: [],
    })

    modeler.value = m

    // 加载初始 XML 或空白模板
    if (props.initialXml) {
      loadXml(props.initialXml)
    } else {
      loadBlankDiagram()
    }

    // 监听变化
    m.on('commandStack.changed', async () => {
      try {
        const result = await m.saveXML({ format: true })
        currentXml.value = result.xml || ''
        const svgResult = await m.saveSVG()
        currentSvg.value = svgResult.svg || ''
      } catch {
        // ignore
      }
    })
  } catch (e) {
    ElMessage.error('BPMN 设计器初始化失败：' + (e as Error).message)
    console.error('BpmnModeler init error:', e)
  } finally {
    loading.value = false
  }
}

async function loadXml(xml: string) {
  if (!modeler.value) return
  loading.value = true
  try {
    await modeler.value.importXML(xml)
    const result = await modeler.value.saveXML({ format: true })
    currentXml.value = result.xml || ''
  } catch (e) {
    ElMessage.error('BPMN XML 导入失败：' + (e as Error).message)
    console.error('importXML error:', e)
  } finally {
    loading.value = false
  }
}

async function loadBlankDiagram() {
  const blank = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
  xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"
  xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"
  xmlns:di="http://www.omg.org/spec/DD/20100524/DI"
  xmlns:flowable="http://flowable.org/bpmn"
  targetNamespace="http://bpmn.io/schema/bpmn">
  <bpmn:process id="Process_1" isExecutable="true">
    <bpmn:startEvent id="StartEvent_1" name="开始">
      <bpmn:outgoing>Flow_1</bpmn:outgoing>
    </bpmn:startEvent>
    <bpmn:endEvent id="EndEvent_1" name="结束">
      <bpmn:incoming>Flow_1</bpmn:incoming>
    </bpmn:endEvent>
    <bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="EndEvent_1" />
  </bpmn:process>
  <bpmndi:BPMNDiagram id="BPMNDiagram_1">
    <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_1">
      <bpmndi:BPMNShape id="StartEvent_1_di" bpmnElement="StartEvent_1">
        <dc:Bounds x="179" y="159" width="36" height="36" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="EndEvent_1_di" bpmnElement="EndEvent_1">
        <dc:Bounds x="432" y="159" width="36" height="36" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNEdge id="Flow_1_di" bpmnElement="Flow_1">
        <di:waypoint x="215" y="177" />
        <di:waypoint x="432" y="177" />
      </bpmndi:BPMNEdge>
    </bpmndi:BPMNPlane>
  </bpmndi:BPMNDiagram>
</bpmn:definitions>`
  await loadXml(blank)
}

// ==================== Actions ====================
async function handleExportXml() {
  if (!currentXml.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  const blob = new Blob([currentXml.value], { type: 'application/xml' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `${deployForm.value.flowCode || 'process'}.bpmn`
  a.click()
  URL.revokeObjectURL(url)
  ElMessage.success('BPMN XML 已导出')
}

async function handleImportXml() {
  const input = document.createElement('input')
  input.type = 'file'
  input.accept = '.bpmn,.xml'
  input.onchange = async (e: Event) => {
    const file = (e.target as HTMLInputElement).files?.[0]
    if (!file) return
    const text = await file.text()
    await loadXml(text)
    ElMessage.success('BPMN XML 已导入')
  }
  input.click()
}

async function handleSave() {
  if (!currentXml.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  saving.value = true
  try {
    emit('save', currentXml.value, currentSvg.value)
    ElMessage.success('流程已保存')
  } finally {
    saving.value = false
  }
}

async function handleDeploy() {
  if (!currentXml.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  if (!deployForm.value.flowCode.trim()) {
    ElMessage.warning('请输入流程编码')
    return
  }
  if (!deployForm.value.flowName.trim()) {
    ElMessage.warning('请输入流程名称')
    return
  }
  saving.value = true
  try {
    const payload: FlowDeployDTO = {
      flowCode: deployForm.value.flowCode.trim(),
      flowName: deployForm.value.flowName.trim(),
      category: deployForm.value.category,
      formPath: deployForm.value.formPath,
      bpmnXml: currentXml.value,
    }
    const res = await deployDefinition(payload)
    if (res.data?.code === 0) {
      ElMessage.success(`流程部署成功，定义 ID: ${res.data.data}`)
      emit('deploy', deployForm.value.flowCode, deployForm.value.flowName, currentXml.value)
    } else {
      ElMessage.error(res.data?.message || '部署失败')
    }
  } catch (e) {
    ElMessage.error('部署失败：' + (e as Error).message)
  } finally {
    saving.value = false
  }
}

function handleReset() {
  loadBlankDiagram()
  ElMessage.success('已重置为空白流程')
}

// ==================== Templates ====================
const templates = [
  {
    label: '空白流程',
    xml: '', // triggers loadBlankDiagram
  },
  {
    label: '请假审批（2级）',
    xml: `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:flowable="http://flowable.org/bpmn" targetNamespace="http://bpmn.io/schema/bpmn">
  <bpmn:process id="Process_Leave" name="请假审批" isExecutable="true">
    <bpmn:startEvent id="StartEvent_1" name="发起请假"/>
    <bpmn:userTask id="Task_Manager" name="直属上级审批" flowable:assignee="\${leader}"/>
    <bpmn:userTask id="Task_HR" name="HR审批" flowable:assignee="\${hr}"/>
    <bpmn:endEvent id="EndEvent_1" name="结束"/>
    <bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Task_Manager"/>
    <bpmn:sequenceFlow id="Flow_2" sourceRef="Task_Manager" targetRef="Task_HR"/>
    <bpmn:sequenceFlow id="Flow_3" sourceRef="Task_HR" targetRef="EndEvent_1"/>
  </bpmn:process>
</bpmn:definitions>`,
  },
  {
    label: '报销审批（含条件）',
    xml: `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:flowable="http://flowable.org/bpmn" targetNamespace="http://bpmn.io/schema/bpmn">
  <bpmn:process id="Process_Expense" name="报销审批" isExecutable="true">
    <bpmn:startEvent id="StartEvent_1" name="发起报销"/>
    <bpmn:userTask id="Task_Manager" name="直属上级审批" flowable:assignee="\${leader}"/>
    <bpmn:exclusiveGateway id="Gateway_Amount" name="金额判断"/>
    <bpmn:userTask id="Task_Director" name="总监审批" flowable:assignee="\${director}"/>
    <bpmn:userTask id="Task_Finance" name="财务审批" flowable:assignee="\${finance}"/>
    <bpmn:endEvent id="EndEvent_1" name="结束"/>
    <bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Task_Manager"/>
    <bpmn:sequenceFlow id="Flow_2" sourceRef="Task_Manager" targetRef="Gateway_Amount"/>
    <bpmn:sequenceFlow id="Flow_3" sourceRef="Gateway_Amount" targetRef="Task_Director">
      <bpmn:conditionExpression xsi:type="bpmn:tFormalExpression">\${amount > 5000}</bpmn:conditionExpression>
    </bpmn:sequenceFlow>
    <bpmn:sequenceFlow id="Flow_4" sourceRef="Gateway_Amount" targetRef="Task_Finance">
      <bpmn:conditionExpression xsi:type="bpmn:tFormalExpression">\${amount <= 5000}</bpmn:conditionExpression>
    </bpmn:sequenceFlow>
    <bpmn:sequenceFlow id="Flow_5" sourceRef="Task_Director" targetRef="Task_Finance"/>
    <bpmn:sequenceFlow id="Flow_6" sourceRef="Task_Finance" targetRef="EndEvent_1"/>
  </bpmn:process>
</bpmn:definitions>`,
  },
  {
    label: '合同审批（并行）',
    xml: `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:flowable="http://flowable.org/bpmn" targetNamespace="http://bpmn.io/schema/bpmn">
  <bpmn:process id="Process_Contract" name="合同审批" isExecutable="true">
    <bpmn:startEvent id="StartEvent_1" name="发起合同"/>
    <bpmn:parallelGateway id="Gateway_Split" name="并行分支"/>
    <bpmn:userTask id="Task_Legal" name="法务审核" flowable:assignee="\${legal}"/>
    <bpmn:userTask id="Task_Finance" name="财务审核" flowable:assignee="\${finance}"/>
    <bpmn:userTask id="Task_Biz" name="业务审核" flowable:assignee="\${biz}"/>
    <bpmn:parallelGateway id="Gateway_Join" name="并行汇聚"/>
    <bpmn:userTask id="Task_CEO" name="CEO审批" flowable:assignee="\${ceo}"/>
    <bpmn:endEvent id="EndEvent_1" name="结束"/>
    <bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Gateway_Split"/>
    <bpmn:sequenceFlow id="Flow_2" sourceRef="Gateway_Split" targetRef="Task_Legal"/>
    <bpmn:sequenceFlow id="Flow_3" sourceRef="Gateway_Split" targetRef="Task_Finance"/>
    <bpmn:sequenceFlow id="Flow_4" sourceRef="Gateway_Split" targetRef="Task_Biz"/>
    <bpmn:sequenceFlow id="Flow_5" sourceRef="Task_Legal" targetRef="Gateway_Join"/>
    <bpmn:sequenceFlow id="Flow_6" sourceRef="Task_Finance" targetRef="Gateway_Join"/>
    <bpmn:sequenceFlow id="Flow_7" sourceRef="Task_Biz" targetRef="Gateway_Join"/>
    <bpmn:sequenceFlow id="Flow_8" sourceRef="Gateway_Join" targetRef="Task_CEO"/>
    <bpmn:sequenceFlow id="Flow_9" sourceRef="Task_CEO" targetRef="EndEvent_1"/>
  </bpmn:process>
</bpmn:definitions>`,
  },
]

function applyTemplate(tpl: (typeof templates)[0]) {
  if (!tpl.xml) {
    loadBlankDiagram()
  } else {
    loadXml(tpl.xml)
  }
  ElMessage.success(`已加载模板：${tpl.label}`)
}
</script>

<template>
  <div class="bpmn-designer">
    <!-- 工具栏 -->
    <div class="bpmn-toolbar">
      <div class="bpmn-toolbar-left">
        <el-dropdown @command="(cmd: string) => { const t = templates.find(x => x.label === cmd); if (t) applyTemplate(t) }">
          <el-button size="small">
            模板 <el-icon class="el-icon--right"><ArrowDown /></el-icon>
          </el-button>
          <template #dropdown>
            <el-dropdown-menu>
              <el-dropdown-item
                v-for="tpl in templates"
                :key="tpl.label"
                :command="tpl.label"
              >{{ tpl.label }}</el-dropdown-item>
            </el-dropdown-menu>
          </template>
        </el-dropdown>
      </div>
      <div class="bpmn-toolbar-right">
        <el-button size="small" @click="handleImportXml">导入 XML</el-button>
        <el-button size="small" @click="handleExportXml" :disabled="!currentXml">导出 XML</el-button>
        <el-button size="small" @click="handleReset">重置</el-button>
        <el-button size="small" type="primary" @click="handleSave" :loading="saving" :disabled="!currentXml">
          保存
        </el-button>
      </div>
    </div>

    <!-- 画布 -->
    <div class="bpmn-canvas" ref="containerRef" v-loading="loading">
      <div v-if="loading" class="bpmn-loading-overlay">
        <span>正在加载 BPMN 设计器...</span>
      </div>
    </div>

    <!-- 部署面板 -->
    <div class="bpmn-deploy-bar">
      <el-input
        v-model="deployForm.flowCode"
        placeholder="流程编码（如 project_initiation）"
        size="small"
        style="width: 200px"
      />
      <el-input
        v-model="deployForm.flowName"
        placeholder="流程名称（如 项目立项审批）"
        size="small"
        style="width: 200px"
      />
      <el-select
        v-model="deployForm.category"
        size="small"
        style="width: 140px"
      >
        <el-option label="通用" value="GENERAL" />
        <el-option label="项目" value="PROJECT" />
        <el-option label="财务" value="FINANCE" />
        <el-option label="人事" value="HR" />
        <el-option label="行政" value="ADMIN" />
        <el-option label="采购" value="PURCHASE" />
      </el-select>
      <el-input
        v-model="deployForm.formPath"
        placeholder="表单路径（可选）"
        size="small"
        style="width: 180px"
      />
      <el-button size="small" type="success" @click="handleDeploy" :loading="saving" :disabled="!currentXml">
        发布部署
      </el-button>
    </div>
  </div>
</template>

